import React from "react";

/**
 * AWS NEXUS — REAL AWS ICON SET (official AWS Architecture Icons package).
 *
 * Two families:
 *
 * 1. Inline glyphs (this file's `*Icon` components) — path data extracted
 *    verbatim from the official AWS Resource-Icons SVGs and re-rendered with
 *    fill="currentColor" so they inherit every status tint in the flow
 *    diagrams exactly like the previous stroke icons did.
 *    Source: AWS Architecture Icons package (Resource-Icons, 48px).
 *
 * 2. Colored architecture tiles (`AWS_ARCH_ICONS` + <AWSIconTile/>) — the
 *    official colored Arch_/Group_ square icons served from /icons/aws/ and
 *    used in the nav rail, module headers and feature panels.
 *    Source: AWS Architecture Icons package (Arch-Service-Icons / Architecture-Group-Icons).
 *    https://aws.amazon.com/architecture/icons/
 *
 * The `strokeWidth` prop is retained for call-site compatibility (no-op on
 * fill-based glyphs).
 */

export interface IconProps {
  className?: string;
  /** Deprecated: no-op for fill-based AWS glyphs (kept for call-site compat). */
  strokeWidth?: number;
}

const base = (className?: string) => className ?? "w-6 h-6";

/* ------------------------------------------------------------------ */
/* INLINE GLYPHS — official AWS resource icon artwork                   */
/* ------------------------------------------------------------------ */

